"use client";

import { useState, useEffect, useCallback } from "react";
import Link from "next/link";
import { ChevronDown, Menu, X, Search } from "lucide-react";
import { WordMark } from "@/components/ui/WordMark";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

const NAV_LINKS = [
  { label: "Opportunities", href: "#opportunities" },
  { label: "For Employers", href: "#employers" },
  { label: "For Colleges", href: "#colleges" },
  { label: "Resources", href: "#resources" },
];

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = useCallback(() => {
    setScrolled(window.scrollY > 4);
  }, []);

  useEffect(() => {
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, [handleScroll]);

  const closeMenu = () => setMenuOpen(false);

  return (
    <>
      <header className={cn("sticky top-0 z-50 h-16 border-b border-slate-100 bg-white/90 backdrop-blur-md transition-shadow duration-200", scrolled && "shadow-sm")}>
        <div className="mx-auto flex h-full max-w-[1400px] items-center gap-6 px-6">
          <Link href="/" aria-label="InternAtlas home" onClick={closeMenu} className="flex-shrink-0 mr-4">
            <WordMark />
          </Link>
          
          <nav aria-label="Primary navigation" className="hidden lg:flex items-center gap-5">
            {NAV_LINKS.map((link) => (
              <Link key={link.href} href={link.href} className="group flex items-center gap-1 text-[14px] font-semibold text-slate-700 transition-colors hover:text-blue-600">
                {link.label}
                <ChevronDown size={14} className="text-slate-400 group-hover:text-blue-600" />
              </Link>
            ))}
          </nav>

          <div className="ml-auto hidden items-center gap-4 lg:flex flex-1 justify-end">
            <div className="relative w-full max-w-sm hidden xl:block">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input type="text" placeholder="Search internships, jobs, competitions..." className="h-9 w-full rounded-full border-slate-200 bg-slate-50 pl-9 pr-4 text-sm shadow-none focus-visible:bg-white" />
            </div>
            <Button variant="ghost" className="h-9 font-semibold text-slate-700 hover:text-slate-900" asChild>
              <Link href="#login">Log in</Link>
            </Button>
            <Button className="h-9 rounded-full bg-slate-900 px-5 font-semibold text-white hover:bg-slate-800" asChild>
              <Link href="#signup">Sign up</Link>
            </Button>
          </div>

          <button className="ml-auto flex h-8 w-8 items-center justify-center rounded-lg text-slate-600 lg:hidden" onClick={() => setMenuOpen((v) => !v)}>
            {menuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </header>
      
      {/* Mobile Menu */}
      <div className={cn("fixed inset-x-0 top-16 z-40 border-b border-slate-200 bg-white px-6 pb-6 shadow-lg lg:hidden transition-all duration-300 ease-out", menuOpen ? "translate-y-0 opacity-100 pointer-events-auto" : "-translate-y-3 opacity-0 pointer-events-none")}>
        <div className="mt-4 mb-4 relative w-full">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <Input type="text" placeholder="Search internships..." className="h-10 w-full rounded-full border-slate-200 bg-slate-50 pl-9 pr-4 text-sm shadow-none" />
        </div>
        <nav className="mb-4 flex flex-col">
          {NAV_LINKS.map((link) => (
            <Link key={link.href} href={link.href} onClick={closeMenu} className="border-b border-slate-100 py-3.5 text-base font-semibold text-slate-700">
              {link.label}
            </Link>
          ))}
        </nav>
        <div className="flex flex-col gap-2.5">
          <Button variant="ghost" className="w-full justify-center" asChild><Link href="#login" onClick={closeMenu}>Log in</Link></Button>
          <Button className="w-full justify-center rounded-full bg-slate-900 text-white hover:bg-slate-800" asChild><Link href="#signup" onClick={closeMenu}>Sign up</Link></Button>
        </div>
      </div>
    </>
  );
}
